def solve(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    seen = [[False] * cols for _ in range(rows)]

    def sink(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return
        if seen[r][c] or not grid[r][c]:
            return
        seen[r][c] = True
        sink(r + 1, c)
        sink(r - 1, c)
        sink(r, c + 1)
        sink(r, c - 1)

    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] and not seen[r][c]:
                count += 1
                sink(r, c)
    return count

